 "content": "def transform(grid):
    from collections import deque
    R,C=len(grid),len(grid[0]); seen=set(); ups=[]; downs=[]
    for r in range(R):
        for c in range(C):
            if grid[r][c]!=2 or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<R and 0<=b<C and grid[a][b]==2 and (a,b) not in seen:
                        seen.add((a,b)); q.append((a,b))
            if len(cells)!=4: continue
            r0=min(x for x,y in cells); c0=min(y for x,y in cells)
            loc={(x-r0,y-c0) for x,y in cells}
            # T stem above bottom-row bar versus stem below top-row bar
            if {(0,1),(1,0),(1,1),(1,2)}==loc: ups.append((r0,c0))
            elif {(0,0),(0,1),(0,2),(1,1)}==loc: downs.append((r0,c0))
    # Output encodes the two stem directions in separate 3x3 panels,
    # in increasing count with marker slots filled across the panel.
    out=[[0]*6 for _ in range(3)]
    for i in range(min(3,len(ups))):
        r,c=((0,0),(0,2),(2,0))[i]; out[r][c]=1
    for i in range(min(3,len(downs))):
        r,c=((0,3),(0,5),(2,3))[i]; out[r][c]=3
    return out
